        value={value.title}
        onChange={(title) => onChange({ title })}
      />
      <BilingualField
        label="Sous-titre"
        value={value.subtitle}
        onChange={(subtitle) => onChange({ subtitle })}
        multiline
        rows={2}
      />

      <Field label="Nombre maximum de catégories affichées">
        <input
          type="number"
          min={1}
          max={20}
          value={value.maxCount}
