                  >
                    {selected && <Check size={12} className="text-black" />}
                  </div>
                </button>
              );
            })}
          </div>
        )}
        <p className="text-[11px] text-neutral-500 mt-1.5">
          Aucune sélection = toutes vos catégories actives sont affichées.
        </p>
      </div>
    </div>
  );
}

