            <div className={`transition-all duration-300 ${deviceMode === "mobile" ? "w-[390px] border-4 border-neutral-800 rounded-3xl shadow-xl overflow-hidden bg-white my-auto" : "w-full"}`}>
              <ThemeStorePreview
